import { useEffect, useState } from 'react';
import { BookOpen, ChevronDown, GitBranch, ArrowUpRight } from 'lucide-react';
import { BIBLE_BOOKS, parseBibleReadingReference, type BibleReadingLocation } from '../lib/bibleBooks';
